CREATE TABLE capacity_allocation(event_id uuid PRIMARY KEY,configured_capacity integer NOT NULL CHECK(configured_capacity>0),policy_version bigint NOT NULL,held_count integer NOT NULL DEFAULT 0 CHECK(held_count>=0),confirmed_count integer NOT NULL DEFAULT 0 CHECK(confirmed_count>=0),version bigint NOT NULL DEFAULT 1,CHECK(held_count+confirmed_count<=configured_capacity));
CREATE TABLE booking(id uuid PRIMARY KEY,account_id uuid NOT NULL,event_id uuid NOT NULL,state text NOT NULL CHECK(state IN('PENDING_PAYMENT','CONFIRMED','EXPIRED','CANCELLED','PAYMENT_REVIEW')),amount numeric(18,2) NOT NULL CHECK(amount>=0),currency char(3) NOT NULL,policy_version bigint NOT NULL,expires_at timestamptz NOT NULL,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL,confirmed_at timestamptz);
CREATE UNIQUE INDEX booking_active_account_event ON booking(account_id,event_id) WHERE state IN('PENDING_PAYMENT','CONFIRMED','PAYMENT_REVIEW');
CREATE INDEX booking_expiry_idx ON booking(expires_at) WHERE state='PENDING_PAYMENT';
CREATE TABLE idempotency_record(actor_id uuid NOT NULL,operation text NOT NULL,idempotency_key text NOT NULL,request_fingerprint text NOT NULL,booking_id uuid NOT NULL REFERENCES booking(id),created_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(actor_id,operation,idempotency_key));
CREATE TABLE inbox(consumer text NOT NULL,event_id uuid NOT NULL,processed_at timestamptz NOT NULL,PRIMARY KEY(consumer,event_id));
CREATE TABLE outbox(event_id uuid PRIMARY KEY,event_type text NOT NULL,schema_version integer NOT NULL,aggregate_id uuid NOT NULL,correlation_id uuid NOT NULL,causation_id uuid,actor_id text,payload jsonb NOT NULL,occurred_at timestamptz NOT NULL,published_at timestamptz,claimed_at timestamptz,attempts integer NOT NULL DEFAULT 0);

